package com.zxl.zxlaiagent.knowledge.scoped;
import com.zxl.zxlaiagent.security.*;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
class WorkerAuthenticationPgTest extends ScopedKnowledgePgTest {
 private static final String TOKEN="abcdefghijklmnopqrstuvwxyz_0123456789-ABCDEFGHIJKLMNO";
 private MockMvc mvc(){return MockMvcBuilders.standaloneSetup(new ScopedKnowledgeController(factory)).addFilters(new WorkerAuthenticationFilter(new ServiceCallAuthorizer(security,authorization),authorization,TOKEN)).build();}
 private String ticket(ActorRef actor,String method,String path,String query,byte[] body){return new ServiceCallAuthorizer(security,authorization).issue(actor,WorkerRequestContract.AUDIENCE,WorkerRequestContract.action(method,path),null,WorkerRequestContract.hash(method,path,query,body));}
 @Test void serviceCredentialAndSingleUseRequestBinding()throws Exception{var mvc=mvc();String path=WorkerRequestContract.BASE+"/documents";mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header("Authorization","Bearer "+TOKEN)).andExpect(status().isUnauthorized());String ticket=ticket(alice,"GET",path,null,new byte[0]);mvc.perform(get(path).header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket)).andExpect(status().isOk());mvc.perform(get(path).header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket)).andExpect(status().isUnauthorized());}
 @Test void bodyTamperingAndWrongAudienceAreDenied()throws Exception{var mvc=mvc();String path=WorkerRequestContract.BASE+"/documents";byte[] body="{}".getBytes();String ticket=ticket(alice,"POST",path,null,body);mvc.perform(post(path).content("{\"tenantId\":\"evil\"}").contentType("application/json").header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket)).andExpect(status().isUnauthorized());String wrong=new ServiceCallAuthorizer(security,authorization).issue(alice,"other","knowledge.manage",null,WorkerRequestContract.hash("POST",path,null,body));mvc.perform(post(path).content(body).contentType("application/json").header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",wrong)).andExpect(status().isUnauthorized());}
 @Test void trustedTicketDoesNotPermitIdentityFieldsOrEvaluation()throws Exception{var mvc=mvc();String path=WorkerRequestContract.BASE+"/answers";byte[] body="{\"question\":\"hello\",\"profile\":\"alice\"}".getBytes();mvc.perform(post(path).content(body).contentType("application/json").header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket(alice,"POST",path,null,body))).andExpect(status().isBadRequest());mvc.perform(get(WorkerRequestContract.BASE+"/evaluation/status").header("Authorization","Bearer "+TOKEN)).andExpect(status().isBadRequest());}
 @Test void rawDocumentReadsFollowTicketActor()throws Exception{factory.knowledge(alice).importDocument("same","a.md","alpha private secret");factory.knowledge(bob).importDocument("same","b.md","beta private secret");String path=WorkerRequestContract.BASE+"/documents/same";var mvc=mvc();String result=mvc.perform(get(path).header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket(bob,"GET",path,null,new byte[0]))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertTrue(result.contains("beta private secret"));assertFalse(result.contains("alpha private secret"));}
 @Test void revocationAfterTicketIssueDeniesBeforeWork()throws Exception{String path=WorkerRequestContract.BASE+"/documents";String ticket=ticket(alice,"GET",path,null,new byte[0]);auth.revoke(alice);mvc().perform(get(path).header("Authorization","Bearer "+TOKEN).header("X-Service-Ticket",ticket)).andExpect(status().isUnauthorized());}
}
